```javascript
import { Mesh, PlaneGeometry, Group } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { vec3, mix, smoothstep, uv, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'features-card-1-label';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // --- Backdrop card surface with engineered gradient ---
  const cardW = 2.4;
  const cardH = 3.0;
  const cardGeo = new THREE.PlaneGeometry(cardW, cardH, 1, 1);

  // Gradient from surface to ink using TSL
  const surfaceColor = new THREE.Color(colors.surface);
  const inkColor = new THREE.Color(colors.ink);

  const cardMat = new MeshBasicNodeMaterial();
  cardMat.colorNode = mix(
    vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
    vec3(inkColor.r, inkColor.g, inkColor.b),
    smoothstep(float(0.0), float(1.0), uv().y)
  );
  cardMat.transparent = true;
  cardMat.opacityNode = float(0.96);

  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardMesh.position.z = 0;
  group.add(cardMesh);

  // --- Image plane (isolated CTA hero image as a foreground accent) ---
  const imagePromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl)
    : Promise.resolve(null);

  let imageMesh = null;
  let imageMat = null;

  imagePromise.then((tex) => {
    if (!tex) return;
    tex.colorSpace = THREE.SRGBColorSpace;
    imageMat = new MeshBasicNodeMaterial();
    imageMat.map = tex;
    imageMat.transparent = true;
    const imgGeo = new THREE.PlaneGeometry(cardW * 0.7, cardH * 0.55);
    imageMesh = new THREE.Mesh(imgGeo, imageMat);
    imageMesh.position.set(0, 0.45, 0.02);
    group.add(imageMesh);

    // entrance fade
    imageMat.opacityNode = uniform(0.0);
    const fadeIn = { v: 0 };
    gsap.to(fadeIn, {
      v: 1.0,
      duration: 0.7,
      ease: 'power2.out',
      delay: 0.15,
      onUpdate: () => { imageMat.opacityNode.value = fadeIn.v; }
    });
  }).catch(() => {});

  // --- Accent bar (signal red, <=10% of frame) ---
  const accentColor = new THREE.Color(colors.accent);
  const accentGeo = new THREE.PlaneGeometry(cardW * 0.72, 0.035);
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.colorNode = vec3(accentColor.r, accentColor.g, accentColor.b);
  accentMat.transparent = true;
  accentMat.opacityNode = float(0.92);
  const accentBar = new THREE.Mesh(accentGeo, accentMat);
  accentBar.position.set(0, -0.75, 0.01);
  group.add(accentBar);

  // --- Text labels via MSDF font atlas ---
  const textObjects = [];
  const paperColor = new THREE.Color(colors.paper);
  const inkTextColor = new THREE.Color(colors.ink);

  for (const item of textItems) {
    if (!item.text) continue;
    const role = item.role || 'body';
    const fontSize = item.typography?.fontSize || (role === 'headline' ? 39 : 14);

    let color = paperColor;
    let align = 'center';

    if (role === 'headline') {
      color = paperColor;
      align = 'center';
    }

    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: `#${color.getHexString()}`,
      align,
      letterSpacingPx: role === 'headline' ? 0.5 : 0
    });

    if (role === 'headline') {
      textObj.position.set(0, -1.05, 0.03);
    } else {
      textObj.position.set(0, -1.05, 0.03);
    }

    textObj.material = textObj.material || undefined;
    if (textObj.material && textObj.material.transparent !== undefined) {
      textObj.material.transparent = true;
    }

    group.add(textObj);
    textObjects.push(textObj);

    // entrance fade-up
    const startOpacity = { v: 0 };
    const startY = textObj.position.y + 0.2;
    const targetY = textObj.position.y;
    textObj.position.y = startY;

    gsap.to(startOpacity, {
      v: 1.0,
      duration: 0.5,
      ease: 'power2.out',
      delay: 0.25,
      onUpdate: () => {
        if (textObj.material && textObj.material.opacity !== undefined) {
          textObj.material.opacity = startOpacity.v;
        }
      }
    });
    gsap.to(textObj.position, {
      y: targetY,
      duration: 0.5,
      ease: 'power2.out',
      delay: 0.25
    });
  }

  // --- Subtle grain plane (foreground depth) ---
  const grainGeo = new THREE.PlaneGeometry(cardW, cardH);
  const grainMat = new MeshBasicNodeMaterial();
  grainMat.transparent = true;
  grainMat.opacityNode = float(0.03);
  grainMat.colorNode = vec3(1.0, 1.0, 1.0);
  const grainMesh = new THREE.Mesh(grainGeo, grainMat);
  grainMesh.position.z = 0.04;
  group.add(grainMesh);

  // --- Card entrance: weighted-settle ---
  group.scale.set(0.96, 0.96, 1.0);
  const settle = { v: 0.96 };
  gsap.to(settle, {
    v: 1.0,
    duration: 0.9,
    ease: 'power4.out',
    onUpdate: () => {
      group.scale.set(settle.v, settle.v, 1.0);
    }
  });

  const opacityCtrl = { v: 0 };
  cardMat.opacityNode = uniform(0.0);
  gsap.to(opacityCtrl, {
    v: 0.96,
    duration: 0.6,
    ease: 'power2.out',
    onUpdate: () => { cardMat.opacityNode.value = opacityCtrl.v; }
  });

  // --- Cleanup ---
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(opacityCtrl);
    gsap.killTweensOf(settle);

    for (const t of textObjects) {
      gsap.killTweensOf(t.position);
      if (t.material && t.material.dispose) t.material.dispose();
      if (t.geometry && t.geometry.dispose) t.geometry.dispose();
    }

    if (imageMat) {
      gsap.killTweensOf(imageMat.opacityNode);
      imageMat.dispose();
    }
    if (imageMesh && imageMesh.geometry) imageMesh.geometry.dispose();

    cardGeo.dispose();
    cardMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    grainGeo.dispose();
    grainMat.dispose();
  };

  // --- No handlers (static composition, no interactivity) ---
  group.userData.handlers = {};

  return group;
}
